WITH "g1" AS (SELECT "t1"."region" AS "region", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN "t0"."net_amount" END) AS "rev_aug", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-06-30 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-07-31 17:00:00' THEN "t0"."net_amount" END) AS "rev_jul" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND (("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') OR ("t0"."order_date" >= TIMESTAMP '2026-06-30 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-07-31 17:00:00')) GROUP BY "t1"."region") SELECT "g1"."region" AS "region", "g1"."rev_aug" AS "rev_aug", "g1"."rev_jul" AS "rev_jul", ("g1"."rev_aug" - "g1"."rev_jul") * 1.0 / NULLIF("g1"."rev_jul", 0) * 100 AS "growth_pct" FROM "g1" WHERE "g1"."rev_jul" > 0 ORDER BY "growth_pct" DESC LIMIT 3
